layer.css:
[data-ryt="pitch"] { color: var(--ryt-header-text); border-left: 12px solid var(--ryt-header-bg); border-radius: 0px; font-family: Georgia, "Times New Roman", Times, serif; font-size: 20px; font-weight: 400; font-style: italic; line-height: 1.556; letter-spacing: 0.16px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-header-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; border-top: none; border-right: none; border-bottom: none }
article[data-ryt="rec-card"] { border-radius: 0px; box-shadow: rgba(51, 51, 102, 0.08) -5px 0px 20px 0px; transition: all }
[data-ryt="footer"] { color: var(--ryt-text); background-color: var(--ryt-bg); font-style: normal; letter-spacing: 0.16px; text-transform: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: 0.16px; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: 0.15s linear }
[data-ryt="hero"] h1 { color: var(--ryt-header-text); font-family: var(--ryt-font-heading); font-size: 24px; font-weight: 700; font-style: normal; line-height: 1.45; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-header-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="review"] { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.75; letter-spacing: 0.16px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: #7e8992; font-family: var(--ryt-font-heading); font-size: 12px; font-weight: 400; font-style: normal; line-height: 1.75; letter-spacing: 0.16px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(140, 152, 162); text-decoration-thickness: auto; text-underline-offset: auto; transition: 0.15s linear }
[data-ryt="cover"] { border-radius: 5px 5px 0px 0px }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-header-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-header-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: 0.15s linear }
[data-ryt="brand"] { color: rgb(59, 66, 162); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 24px; font-weight: 700; font-style: normal; line-height: 1.75; letter-spacing: 0.16px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(59, 66, 162); text-decoration-thickness: auto; text-underline-offset: auto; transition: 0.15s linear }
[data-ryt="nav"] a { color: var(--ryt-header-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 600; font-style: normal; line-height: 1.857; letter-spacing: 0.16px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-header-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 32px; padding-right: 8px; padding-bottom: 32px; padding-left: 8px; transition: 0.15s linear }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-header-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 24px; font-weight: 700; font-style: normal; line-height: 1.45; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-header-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a:hover { color: rgb(0, 86, 179); text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: color-mix(in srgb, var(--ryt-text) 70%, transparent); text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; outline-color: initial; color: rgb(93, 93, 93); text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="brand"]:hover { color: rgb(0, 86, 179); text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: color-mix(in srgb, var(--ryt-text) 90%, transparent); text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; outline-color: initial; color: rgb(93, 93, 93); text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { color: rgb(0, 86, 179); text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; outline-color: initial; color: rgb(93, 93, 93); text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="credit"]:hover, [data-ryt="eyebrow"]:hover { color: rgb(0, 86, 179); text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; outline-color: initial; color: rgb(93, 93, 93); text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { color: rgb(0, 86, 179); text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; outline-color: initial; color: rgb(93, 93, 93); text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
